#region "BusinessLogicPlugin"
public class BusinessLogicPlugin : System.MarshalByRefObject, JiwaFinancials.Jiwa.JiwaApplication.IJiwaBusinessLogicPlugin
{

    public override object InitializeLifetimeService()
    {
        // returning null here will prevent the lease manager
        // from deleting the Object.
        return null;
    }

    public void Setup(JiwaFinancials.Jiwa.JiwaApplication.IJiwaBusinessLogic JiwaBusinessLogic, JiwaFinancials.Jiwa.JiwaApplication.Plugin.Plugin Plugin)
    {
		if(JiwaBusinessLogic is JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrder)
		{
			JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrder salesOrder =(JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrder)JiwaBusinessLogic;
			salesOrder.CreateEnd += SalesOrder_CreateEnd;			
		}
		else if(JiwaBusinessLogic is JiwaFinancials.Jiwa.JiwaSales.SalesQuote.SalesQuote)
		{
			JiwaFinancials.Jiwa.JiwaSales.SalesQuote.SalesQuote salesQuote =(JiwaFinancials.Jiwa.JiwaSales.SalesQuote.SalesQuote)JiwaBusinessLogic;
			salesQuote.CreateEnd += SalesQuote_CreateEnd;			
		}

    }
	
	private void SalesOrder_CreateEnd(object sender, System.EventArgs e)
	{
		JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrder salesOrder =(JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrder)sender;					
		JiwaFinancials.Jiwa.JiwaODBC.database db = salesOrder.Manager.Database;
		SqlParameter SQLParam = null;
		SqlDataReader SQLReader = null;
		
		try
		{
		 	string SQL = "SELECT Contents FROM IN_LogicalWarehouseCustomValues WHERE IN_LogicalWarehouseCustomFields_RecID = (SELECT TOP 1 RecID FROM IN_LogicalWarehouseCustomFields WHERE SettingName = 'Branch') AND IN_Logical_RecID = @IN_LogicalID";
			
			using (SqlCommand SQLCmd = new SqlCommand(SQL, db.SQLConnection, db.SQLTransaction))
			{
				SQLParam = new SqlParameter("@IN_LogicalID", System.Data.SqlDbType.Char);
            	SQLParam.Value = salesOrder.LogicalWarehouseResidingIn.IN_LogicalID;
            	SQLCmd.Parameters.Add(SQLParam);
				
				SQLReader = SQLCmd.ExecuteReader();
					
				if (SQLReader.Read())
				{
					string branchID = db.Sanitise(SQLReader, "Contents").ToString();
					if (branchID.Trim().Length > 0)
						salesOrder.Branch.ReadRecord(db.Sanitise(SQLReader, "Contents").ToString());
				}
				else
					throw new JiwaFinancials.Jiwa.JiwaApplication.Exceptions.RecordNotFoundException(String.Format("Logical Warehouse '{0}' does not have a branch associated with it.  Set this via the Warehouse maintenance form.", salesOrder.LogicalWarehouseResidingIn.Description));
			}
				
			SQLReader.Close();
		}
		finally
		{
			if (SQLReader != null)
				SQLReader.Close();				
		}

	}
	
	private void SalesQuote_CreateEnd(object sender, System.EventArgs e)
	{
		JiwaFinancials.Jiwa.JiwaSales.SalesQuote.SalesQuote salesQuote =(JiwaFinancials.Jiwa.JiwaSales.SalesQuote.SalesQuote)sender;					
		JiwaFinancials.Jiwa.JiwaODBC.database db = salesQuote.Manager.Database;
		SqlParameter SQLParam = null;
		SqlDataReader SQLReader = null;
		
		try
		{
		 	string SQL = "SELECT Contents FROM IN_LogicalWarehouseCustomValues WHERE IN_LogicalWarehouseCustomFields_RecID = (SELECT TOP 1 RecID FROM IN_LogicalWarehouseCustomFields WHERE SettingName = 'Branch') AND IN_Logical_RecID = @IN_LogicalID";
			
			using (SqlCommand SQLCmd = new SqlCommand(SQL, db.SQLConnection, db.SQLTransaction))
			{
				SQLParam = new SqlParameter("@IN_LogicalID", System.Data.SqlDbType.Char);
            	SQLParam.Value = salesQuote.LogicalWarehouseResidingIn.IN_LogicalID;
            	SQLCmd.Parameters.Add(SQLParam);
				
				SQLReader = SQLCmd.ExecuteReader();
					
				if (SQLReader.Read())
				{
					string branchID = db.Sanitise(SQLReader, "Contents").ToString();
					if (branchID.Trim().Length > 0)
						salesQuote.Branch.ReadRecord(db.Sanitise(SQLReader, "Contents").ToString());
				}
				else
					throw new JiwaFinancials.Jiwa.JiwaApplication.Exceptions.RecordNotFoundException(String.Format("Logical Warehouse '{0}' does not have a branch associated with it.  Set this via the Warehouse maintenance form.", salesQuote.LogicalWarehouseResidingIn.Description));
			}
				
			SQLReader.Close();
		}
		finally
		{
			if (SQLReader != null)
				SQLReader.Close();				
		}

	}	
}
#endregion

